    var dv = (drivers || []).filter(function (d) { return BIO_nameKey(d.name) === q && byId[BIO_norm(d.vehicleId)]; }).map(function (d) { return byId[BIO_norm(d.vehicleId)]; });
    var h1 = one(ex.concat(dv));
    if (h1) return res(h1, 'اسم السائق ' + String(raw).trim(), true);
    if (!ex.length && !dv.length && q.indexOf(' ') > 0) { var h2 = one(active.filter(function (i) { var k = BIO_nameKey(i.name); return k.indexOf(q + ' ') === 0 || q.indexOf(k + ' ') === 0; })); if (h2) return res(h2, 'اسم السائق ' + String(raw).trim()); }
