    if (ctx.kind == null) ctx.kind = it ? String(it.kind || '') : '';
    if (ctx.exempt === undefined) { ctx.exempt = BIO_isLeaveVeh(it) ? BIO_LEAVE_EX : it && ctx.settings && ctx.settings.ISO_EXEMPT ? BIO_isoExFor(ctx.settings, it, ctx.now) : null; if (ctx.exempt) ctx.exempt = Object.assign({}, ctx.exempt, { alias: BIO_coAlias(it) }); }
