    var score = scored.length ? Math.round(scored.reduce(function (a, g) { return a + g.score * Math.max(1, g.n); }, 0) / scored.reduce(function (a, g) { return a + Math.max(1, g.n); }, 0)) : null;
    var totals = { moves: tot }; ['manual', 'missing', 'impossible', 'burst', 'late', 'overrides'].forEach(function (k) { totals[k] = Object.keys(G).reduce(function (a, x) { return a + (G[x][k] || 0); }, 0); });
