    try { d = api.dashboard(pin); } catch (e) { d = null; }
    if (d) { m.threat = d.threat || []; m.threatTop = d.threatTop || null; m.threatScale = d.threatScale || []; m.brief = d.brief || []; m.kpis = d.cmp ? d.cmp.kpis : []; m.stats = d.stats || null; }
