    o = o || {}; var out = {};
    if (o.annual != null) { var a = Math.round(Number(o.annual)); if (!(a >= 1000 && a <= 500000000)) throw new Error('عدد الطيور السنوي غير منطقي'); setSetting('ANNUAL_BIRDS', a, 'عدد الطيور المستهدف حمايتها في السنة'); out.annual = a; }
    if (o.value != null) { var v = Number(o.value); if (!(v >= 0 && v <= 100000)) throw new Error('قيمة الطائر غير منطقية'); setSetting('BIRD_VALUE_EGP', v, 'متوسط قيمة الطائر بالجنيه (تقديري، لحساب القيمة تحت الحماية)'); out.value = v; }
