    var g = H.gateFor(u, sites); if (!g.id) return { score: null };
    var it = integrity({ scope: { all: true }, isManager: true, isAdmin: true, perms: [] }, now, sites, H.allMoves(), 7).gates.filter(function (x) { return x.id === g.id || x.name === g.name; })[0];
