      if (spring) heading = (heading + 180) % 360;
      var tr = track(heading), toSite = BIO_bearing(n.pt, p), al = n.d < 10 ? 1 : Math.max(0, Math.cos(BIO_rad(BIO_angDiff(tr.b, toSite))));
      var prox = Math.exp(-n.d / 45), sc = 62 * x.I * prox * (0.3 + 0.7 * al * al);
      parts.push(sc);
