    { k: BIO.ROLE_SUPERVISOR, label: 'مشرف أمن حيوي', desc: 'يشرف على مجموعة محطات: يحرر تقارير الأمن الحيوي ويتابع بلاغات محطاته ولوحتها', scope: 'site', perms: ['reports', 'analytics', 'vr_write', 'vr_view'] }
