TABLES.drivers = { sheet: 'السائقون على المركبات', key: 'id', cols: { id: 'الرقم', vehicleId: 'كود المركبة', vehicleName: 'المركبة', plate: 'رقم اللوحة', name: 'السائق', count: 'مرات الدخول', first: 'أول مرة', last: 'آخر مرة', gate: 'البوابة' } };
