        present: c['حضور'] + c['مأمورية'], rest: c['راحة'], leaveDays: c['نزول'], leaves: leaves, absent: c['غياب'], sick: c['مرضي'], streak: streak, lastReturn: lastBreak ? dayKey(Date.parse(lastBreak) + D + 12 * BIO.HOUR - 3 * BIO.HOUR) : L[0].day, comp: denom ? Math.round((c['حضور'] + c['مأمورية']) / denom * 1000) / 10 : null, needRest: streak >= maxStreak,
