    if (kind !== 'صرف' && !canData(u)) throw new Error('تسجيل الوارد والتالف والجرد لمن لديه صلاحية البيانات');
    var p = store.find('disProducts', BIO_norm(m.productId)); if (!p) throw new Error('اختر المنتج');
    var qty = num(m.qty, NaN); if (isNaN(qty) || (kind !== 'جرد' && qty <= 0)) throw new Error('اكتب الكمية');
    if (Math.abs(qty) > 100000) throw new Error('الكمية غير منطقية');
