    deps.lock(function () { store.append('disChecks', row); });
    if (result === 'خارج الحدود') deps.notify({ kind: 'request', siteId: pt.serves[0] || '', title: '🧪 تركيز مطهر خارج الحدود: ' + pt.name, body: (pr ? pr.name + ' · ' : '') + 'القراءة ' + reading + ' ' + (g ? g.unit + ' (المسموح ' + g.lo + '-' + g.hi + ')' : '') + '\nسجّلها ' + u.name + '. المطلوب إعادة تحضير المحلول فوراً.' + H.appUrl('#dis') });
