function BIO_seedV21(s, now) {
  var D = 24 * BIO.HOUR, H = BIO.HOUR, d0 = now - ((now + 3 * H) % D) + 12 * H, X = BIO_SEED21;
  var dk = function (off) { var d = new Date(d0 + off * D + 3 * H); return d.getUTCFullYear() + '-' + ('0' + (d.getUTCMonth() + 1)).slice(-2) + '-' + ('0' + d.getUTCDate()).slice(-2); };
  var sid = function (n) { return 'W-F' + ('0' + n).slice(-2); }, nm = {};
  (s.sites || []).forEach(function (x) { nm[x.id] = x.name; if (x.id === 'W-F21') x.type = 'بطاريات'; });
  // المراحل تأتي من ملف البيانات: نحذف المراحل اليدوية التجريبية لمحطات التسمين
  s.phases = (s.phases || []).filter(function (p) { return !/^W-F\d/.test(p.siteId); });
  s.daily = (s.daily || []).filter(function (x) { return !/^W-F\d/.test(x.siteId); });
  X.daily.forEach(function (r) {
    var id = sid(r[0]); if (!nm[id]) return;
    s.daily.push({ id: dk(r[1]) + '|' + id, day: dk(r[1]), siteId: id, siteName: nm[id], farm: 'Wahat ' + r[0], cycle: r[2], status: r[3], age: r[4], houses: r[5], stock: r[6], placed: r[7], dead: r[8], killed: r[9], inj: r[10], feed: r[11], sold: r[12], source: r[13], breed: 'Ross 308', detail: JSON.stringify(r[14].map(function (h) { return { h: h[0], s: h[1], d: h[2], a: h[3], st: h[4] }; })), importId: 'FI-SEED21', time: now });
  });
  s.cycles = X.cycles.filter(function (c) { return nm[sid(c[0])]; }).map(function (c) { var id = sid(c[0]); return { id: id + '|' + c[1], siteId: id, siteName: nm[id], cycle: c[1], houses: c[2], first: dk(c[3]), last: dk(c[4]), saleFrom: c[5] == null ? '' : dk(c[5]), placed: c[6], sold: c[7], dead: c[8], maxAge: c[9], sources: c[10], importId: 'FI-SEED21', time: now }; });
  var q = 0;
  s.plan = X.plan.filter(function (p) { return nm[p[1]]; }).map(function (p) { return { id: dk(p[0]) + '|' + p[1] + '|' + p[2] + '|' + (++q), day: dk(p[0]), siteId: p[1], siteName: nm[p[1]], farm: 'Wahat ' + Number(p[1].slice(3)), source: p[2], houses: p[3], area: p[4], density: p[5], chicks: p[6], importId: 'PL-SEED21', time: now }; });
  s.settings = (s.settings || []).filter(function (x) { return x.key !== 'PLAN_LAST'; });
  s.settings.push({ key: 'PLAN_LAST', value: JSON.stringify({ id: 'PL-SEED21', file: 'خطة تسكين التسمين (مثال من خطة الإنتاج)', time: now - 5 * H, by: 'مدير الأمن الحيوي (مثال)', rows: s.plan.length, from: s.plan.length ? s.plan[0].day : '', to: s.plan.length ? s.plan[s.plan.length - 1].day : '' }), note: 'آخر ملف خطة تسكين مرفوع' });
  return s;
}
