    var row = { id: id, name: name, group: gk, active: cl(p.active, 120), unit: cl(p.unit, 10) || 'لتر', price: Math.max(0, nm(p.price, 0)), uses: Object.keys(dil).join(','), dil: JSON.stringify(dil), contact: Math.max(0, nm(p.contact, 0)), supplier: cl(p.supplier, 80), minDays: Math.max(0, nm(p.minDays, 0)), status: p.on === false ? 'موقوف' : 'فعال', note: cl(p.note, 200),
      kind: BIO_DIS_PKINDS.indexOf(p.kind) >= 0 ? p.kind : '', conc: cl(p.conc, 40), prep: cl(p.prep, 300), places: cl(p.places, 300), method: cl(p.method, 600), prog: cl(p.prog, 200) };
