      var id = BIO_norm(x.id), r = BIO_role(x.role) || {}, z = seen[id] || null, t = z ? Number(z.t) || 0 : 0, g = x.gate ? (store.find('checkpoints', x.gate) || sites[BIO_norm(x.gate)] || null) : null;
