  /* ---------- قيمة الطائر من البورصة ---------- */
  function setS(key, value, note) { if (store.find('settings', key)) store.update('settings', key, { value: value }); else store.append('settings', { key: key, value: value, note: note || '' }); }
  function cairoDay(t) { return new Date(t + 3 * BIO.HOUR).toISOString().slice(0, 10); }
  /** تحديث السعر: يجرّب مصادر الإعداد BIRD_PRICE_URLS بالترتيب، ويرفض الصفحة القديمة (أقدم من يومين) */
  api._priceTick = function (force) {
    var S = H.settings(), now = deps.now(), today = cairoDay(now);
    if (!force && String(S.BIRD_PRICE_PAGE || '') === today && num(S.BIRD_PRICE_KG, 0) > 0) return { skip: 'today' };
    if (!deps.fetchText) return { error: 'لا يوجد اتصال بالإنترنت من الخادم' };
    var urls = String(S.BIRD_PRICE_URLS || BIO_PRICE_URLS).split(/[\s,]+/).filter(String), errs = [];
    for (var i = 0; i < urls.length; i++) {
      try {
        var html = deps.fetchText(urls[i]), p = BIO_birdPrice(html);
        if (!p) { errs.push(urls[i] + ': لم أجد سعر الفراخ البيضاء (' + BIO_priceWhy(html) + ')'); continue; }
        if (p.date && (Date.parse(today) - Date.parse(p.date)) / D > 2) { errs.push(urls[i] + ': الصفحة لم تتحدث منذ ' + p.date); continue; }
        var kgW = num(S.BIRD_KG, 2.2), host = urls[i].replace(/^https?:\/\/(www\.)?/, '').split('/')[0];
        deps.lock(function () {
          setS('BIRD_PRICE_KG', p.kg, 'سعر كيلو الفراخ البيضاء الحية من البورصة (تلقائي)');
          setS('BIRD_PRICE_DAY', today, 'يوم آخر تحديث لسعر البورصة');
          setS('BIRD_PRICE_PAGE', p.date || today, 'تاريخ صفحة البورصة المقروءة');
          setS('BIRD_PRICE_AT', now, 'وقت آخر تحديث لسعر البورصة');
          setS('BIRD_PRICE_SRC', host, 'مصدر سعر البورصة');
          if (String(S.BIRD_VALUE_MODE || '') !== 'يدوي') setS('BIRD_VALUE_EGP', Math.round(p.kg * kgW), 'قيمة الطائر = سعر كيلو البورصة × متوسط وزن الطائر عند البيع (تلقائي يومياً)');
          var hist = json(S.BIRD_PRICE_HIST, []); hist = hist.filter(function (x) { return x[0] !== today; }); hist.push([today, p.kg]); setS('BIRD_PRICE_HIST', JSON.stringify(hist.slice(-60)), 'سعر البورصة آخر 60 يوم');
        });
        return { ok: true, kg: p.kg, value: Math.round(p.kg * kgW), src: host, date: p.date || today };
      } catch (e) { errs.push(urls[i] + ': ' + (e && e.message || e)); }
    }
    deps.lock(function () { setS('BIRD_PRICE_ERR', errs.join(' | ').slice(0, 400) + ' · ' + today, 'آخر خطأ في قراءة سعر البورصة'); });
    return { error: errs.join(' | ') };
  };
  /** زر «تحديث الآن» في غرفة الإدارة العليا */
  api.priceRefresh = function (pin) { var u = H.auth(pin, true); if (!(u.isAdmin || (u.perms || []).indexOf('data') >= 0)) throw new Error('للمدير فقط'); var r = api._priceTick(true); if (r.error) throw new Error('تعذر قراءة سعر البورصة الآن: ' + r.error); return r; };
  var ds0 = api.directorSet;
