    log(u, 'evals', id, ex ? (String(ex.status) === 'معتمد' ? 'تعديل تقييم معتمد' : 'تعديل تقييم') : approve ? 'تقييم معتمد' : 'تقييم موظف', ex ? { total: num(ex.total, 0), status: String(ex.status) } : null, { job: j.label, emp: name, total: tot });
