    var st = H.settings(), now = deps.now(), old = BIO_isoExList(st), V = {}, T = BIO_VEHICLE_TYPES.map(function (t) { return t.k; }).concat(BIO_EQUIP_TYPES.map(function (t) { return 'معدة: ' + t; })), C = {};
